-- ============================================================
--  測試資料補充檔（純資料，不含任何資料表結構）
-- ============================================================
--
--  為什麼需要：
--  ckd101_g1.sql 裡 book_thoughts 是 0 筆、book_collection 只有 1 筆，
--  匯入之後書籍詳情頁看不到任何心得、書房也幾乎沒有藏書，
--  「寫心得」「檢舉心得」「加入藏書」這幾條動線都沒有東西可以 demo。
--
--  怎麼用：
--    1. 先照原本的方式匯入 ckd101_g1.sql（結構 + 基本資料）
--    2. 再匯入這一個檔案
--    3. 之後重新匯出給老師時，匯出的檔案就會含這些測試資料
--
--  內容：
--    member          6 個測試帳號（user_id 63~68）
--    book_thoughts   32 則心得
--    book_collection 32 筆藏書
--
--  ⚠️ 全部用 INSERT IGNORE，重複匯入不會出錯，也不會蓋掉既有資料。
--  ⚠️ 資料原本是用 scripts/seed.mjs 走真實 API 產生的（註冊→登入→發心得→加藏書），
--     所以外鍵關聯都是對的，這裡只是把結果匯出來。
--  ⚠️ 測試帳號密碼＝帳號裡那個數字重複六次：test1@seed.test / 111111，到 test6。
--     沒有任何權限，但線上是真的登得進去，別拿去做別的事。
--
-- ============================================================

SET FOREIGN_KEY_CHECKS = 0;
INSERT  IGNORE INTO `member` (`user_id`, `member_code`, `nickname`, `report_count`, `email`, `password`, `session_token`, `bio`, `avatar_url`, `account_status`, `created_at`, `total_exp`, `last_online_at`) VALUES (63,'MKD00000063','夜貓讀者',0,'test1@seed.test','$2y$10$TQNAUjiWwqAYrBIGYFZjCOYMZ8mIv.QqdjM7ZmzInHI//NXqSY68i',NULL,NULL,NULL,'正常','2026-09-01 14:16:26',0,NULL),(64,'MKD00000064','慢慢看',0,'test2@seed.test','$2y$10$UoUMJvVb/BOC8NzAwZ5YmOy9.7vnOlZYBOxeA44.rOM5lepoAHyeK',NULL,NULL,NULL,'正常','2026-09-01 14:16:26',0,NULL),(65,'MKD00000065','一頁君',0,'test3@seed.test','$2y$10$AMcbbU4qbgLPZxrOBC6Bm.iLawOLLXJ0b4YWX3adlWB3Sm0PpHkyu',NULL,NULL,NULL,'正常','2026-09-01 14:16:26',0,NULL),(66,'MKD00000066','林小滿',0,'test4@seed.test','$2y$10$ByzV7p7YCVEp8Q2lQ5pa4usmOnq6myt7Wd.jmKn5I4/sFs.XY89Rq',NULL,NULL,NULL,'正常','2026-09-01 14:16:27',0,NULL),(67,'MKD00000067','通勤書蟲',0,'test5@seed.test','$2y$10$xNcyzdHrCWJwiSt0naBFB.HIwfnTkiMLq.OW2Tij1YUlu4V./hWXu',NULL,NULL,NULL,'正常','2026-09-01 14:16:27',0,NULL),(68,'MKD00000068','老周',0,'test6@seed.test','$2y$10$rvVMnUoN9EUM1PyNgOf77uhj3xtTpgg33ZWTAp9F5IKk89ZxSyeI2',NULL,NULL,NULL,'正常','2026-09-01 14:16:27',0,NULL);
INSERT  IGNORE INTO `book_thoughts` (`b_thought_id`, `user_id`, `book_id`, `bth_content`, `updated_at`, `bth_status`) VALUES (1,5,1,'這本書把「習慣」拆解成提示、渴望、回應、獎賞四個步驟，讀完最有用的是那句「你不會提升到目標的高度，你只會下降到系統的水準」。我照著把跑步鞋放在門口，兩週沒斷過。','2026-07-14 21:36:00','公開'),(2,6,1,'前半段很精彩，後半段有點重複。不過「兩分鐘法則」真的好用，任何習慣先縮到兩分鐘就開始，門檻低到沒有藉口。','2026-08-02 10:12:00','公開'),(3,4,1,'買來放了半年才翻，後悔沒早點看。作者一直強調環境比意志力重要，這點跟我自己的經驗完全吻合。','2026-08-25 23:41:00','公開'),(4,1,1,'這則是非公開的，前台書籍詳情頁不應該看得到。','2026-08-09 08:55:00','非公開'),(5,38,1,'這則是草稿，前台也不應該看得到。','2026-08-28 19:20:00','儲存草稿'),(253,63,1,'最有用的是那句「你不會提升到目標的高度，你只會下降到系統的水準」。我照著把跑步鞋放門口，兩週沒斷過。','2026-07-28 09:19:00','公開'),(254,64,1,'前半段很精彩，後半段有點重複。不過「兩分鐘法則」真的好用，任何習慣先縮到兩分鐘就開始，門檻低到沒有藉口。','2026-06-21 12:02:00','公開'),(255,65,1,'買來放了半年才翻，後悔沒早點看。作者一直強調環境比意志力重要，這點跟我自己的經驗完全吻合。','2026-08-11 15:45:00','公開'),(256,68,1,'講的東西不算新，但整理得很清楚。適合當工具書隨時翻，不太適合一口氣讀完。','2026-07-05 18:28:00','公開'),(257,64,2,'「課題分離」這四個字讓我重新想了一次跟家人的相處。不是每件事都是我的責任，這件事我花了三十年才懂。','2026-08-25 07:11:00','公開'),(258,66,2,'對話體讀起來很快，但有些地方哲學家的回答太理所當然了，年輕人被說服得有點容易。','2026-07-19 10:54:00','公開'),(259,67,2,'第一次讀覺得被冒犯，第二次讀覺得被救了。建議中間隔一段時間再讀第二次。','2026-06-12 13:37:00','公開'),(260,63,3,'它談的不是怎麼賺錢，是人為什麼會做出愚蠢的財務決定。看完最大的改變是不再看盤了。','2026-08-02 16:20:00','公開'),(261,68,3,'「合理比理性重要」那章值回票價。承認自己會恐慌，然後預留空間，比假裝自己很冷靜有用。','2026-06-26 19:03:00','公開'),(262,67,4,'觀念的啟蒙書。「窮人為錢工作，富人讓錢為自己工作」這句話當年看完，我才第一次認真去查什麼叫資產。','2026-08-16 08:46:00','公開'),(263,65,4,'故事講得好，但書裡的房地產操作放在現在的台灣不太適用，看觀念就好，別照著做。','2026-07-10 11:29:00','公開'),(264,68,4,'重複的地方很多，兩百頁的內容講了三百頁。不過對完全沒有理財概念的人來說，是很好的第一本。','2026-08-30 14:12:00','公開'),(265,66,4,'最有感的是「你的房子不是資產」那一段，直接推翻我爸媽教我的東西，看完跟家裡吵了一架。','2026-07-24 17:55:00','公開'),(266,65,8,'很厚，但每一章都有東西。系統一系統二的分法看完之後，會開始注意到自己什麼時候在偷懶。','2026-06-17 20:38:00','公開'),(267,67,8,'老實說讀得很吃力，實驗細節太多。建議先看每章結尾的整理，有興趣再回頭看過程。','2026-08-07 09:21:00','公開'),(268,66,8,'看完最大的收穫是知道「我以為我在思考」這件事有多常是假的。有點打擊但很值得。','2026-07-01 12:04:00','公開'),(269,64,17,'不劇透，但最後那幾頁我真的坐在捷運上發呆了很久。詭計本身不算最強，情感的重量才是。','2026-08-21 15:47:00','公開'),(270,63,17,'第二次讀才看懂前面埋的線。東野圭吾厲害的地方是你知道兇手是誰，卻還是想一直看下去。','2026-07-15 18:30:00','公開'),(271,68,17,'推理的部分其實猜得到，但那不是重點。這本書真正在問的是一個人可以為另一個人做到什麼程度。','2026-06-08 07:13:00','公開'),(272,66,22,'二十歲讀跟三十歲讀完全是兩本書。年輕時覺得直子很美，現在覺得綠子才是活著的那個。','2026-07-29 10:56:00','公開'),(273,65,22,'氣氛營造無可挑剔，但角色的對話有時候太文青了，讀起來會出戲。喜歡的人會很喜歡。','2026-06-22 13:39:00','公開'),(274,67,23,'節奏很慢，但那個慢是刻意的。一個活很久的人回頭看短命同伴留下的東西，讀起來安靜又難過。','2026-08-12 16:22:00','公開'),(275,63,23,'第一集就把整部作品的核心講完了：勇者一行人的旅程結束之後，剩下的人要怎麼活。','2026-07-06 19:05:00','公開'),(276,68,25,'概念很簡單，但「以自己為主軸，而不是以物品為主軸」這個切換點講得很好。丟了三箱東西。','2026-08-26 08:48:00','公開'),(277,66,25,'前面很有共鳴，後面開始講心靈層面就有點玄了。當成整理術的入門書看剛好。','2026-07-20 11:31:00','公開'),(278,66,1,'這則是非公開的，書籍詳情頁不應該看得到。','2026-06-13 14:14:00','非公開'),(279,63,2,'這則還沒寫完，是草稿。','2026-08-03 17:57:00','儲存草稿');
